#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.maplewheel_Evoke)]
    public class Maplewheel_Evoke : ContraptionEvokeBehaviour
    {
        public Maplewheel_Evoke(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new IntModifier(EngineEntityProps.COLLISION_MASK_FRIENDLY, IntegerOperator.BitOr, EntityCollisionHelper.MASK_PROJECTILE));
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);
            Whirlwind(entity);
        }
        public static void Whirlwind(Entity entity)
        {
            var buff = entity.AddBuff<WhirlwindAttackBuff>();
            WhirlwindAttackBuff.SetTimes(buff, entity.Level.GetEntityCount(VanillaContraptionID.maplewheel));
            WhirlwindAttackBuff.SetDamage(buff, entity.GetDamage() * DAMAGE_MULTIPLIER);
            entity.PlaySound(VanillaSoundID.whirlwindAttackStart);
        }
        public const float DAMAGE_MULTIPLIER = 2.5f;
    }
}
